import React from 'react';
import { Button, resolveSystemLogoSrc } from '@linm-soft-org/linm-web-common-components';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import styles from './IncidentPublicReportGuestPage.module.css';

interface GuestPublicReportHeaderProps {
  title: string;
  subtitle?: string;
  companyCode: string;
  label: (key: string) => string;
  showHistory?: boolean;
  showCreate?: boolean;
}

export const GuestPublicReportHeader: React.FC<GuestPublicReportHeaderProps> = ({
  title,
  subtitle,
  companyCode,
  label,
  showHistory = false,
  showCreate = false,
}) => {
  const appNavigate = useAppNavigate();

  return (
    <div className={styles.header}>
      <div className={styles.headerInner}>
        <div className={styles.brand}>
          <h1>{title}</h1>
          {subtitle ? <p>{subtitle}</p> : null}
          {showHistory && (
            <button
              type="button"
              className={styles.linkBtn}
              onClick={() => appNavigate(scykRoutes.publicReports.guestHistory(companyCode))}
            >
              {label('historyLink')}
            </button>
          )}
        </div>
        <div className={styles.headerRight}>
          {showCreate && label('createReport') !== 'createReport' && (
            <Button
              variant="primary"
              onClick={() => appNavigate(scykRoutes.publicReports.guest(companyCode))}
              data-testid="incident-public-report-guest-create"
            >
              <i className="fas fa-plus" /> {label('createReport')}
            </Button>
          )}
          <img
            className={styles.headerLogo}
            src={resolveSystemLogoSrc()}
            alt=""
            width={40}
            height={40}
            data-testid="incident-public-report-guest-logo"
          />
        </div>
      </div>
    </div>
  );
};
